import { supabase } from '../lib/supabase'

const PAYFAST_MERCHANT_ID = process.env.REACT_APP_PAYFAST_MERCHANT_ID || '36412593'
const PAYFAST_MERCHANT_KEY = process.env.REACT_APP_PAYFAST_MERCHANT_KEY || 'zljtf3msm3wht'
const PAYFAST_PASSPHRASE = process.env.REACT_APP_PAYFAST_PASSPHRASE || ''
const MODE = process.env.REACT_APP_PAYFAST_MODE || 'sandbox'

const PAYFAST_URL = MODE === 'sandbox' 
    ? 'https://sandbox.payfast.co.za/eng/process'
    : 'https://www.payfast.co.za/eng/process'

// Generate a unique reference
function generateReference(communityId, userId) {
    const timestamp = Date.now()
    const random = Math.random().toString(36).substring(2, 8)
    return `PF-${communityId.substring(0, 4)}-${userId.substring(0, 4)}-${timestamp}-${random}`
}

// Generate PayFast form data
export function generatePayFastData(communityId, userId, amount, itemName) {
    const reference = generateReference(communityId, userId)
    
    return {
        merchant_id: PAYFAST_MERCHANT_ID,
        merchant_key: PAYFAST_MERCHANT_KEY,
        return_url: process.env.REACT_APP_PAYFAST_RETURN_URL,
        cancel_url: process.env.REACT_APP_PAYFAST_CANCEL_URL,
        notify_url: process.env.REACT_APP_PAYFAST_NOTIFY_URL,
        m_payment_id: reference,
        amount: amount.toFixed(2),
        item_name: itemName,
        item_description: `Monthly subscription to ${itemName}`,
        custom_str1: communityId,
        custom_str2: userId,
        email_confirmation: '1',
        confirmation_address: 'info@predictfc.com'
    }
}

// Generate the PayFast form HTML
export function generatePayFastForm(payfastData) {
    const formHtml = `
        <form id="payfastForm" method="POST" action="${PAYFAST_URL}">
            ${Object.entries(payfastData).map(([key, value]) => 
                `<input type="hidden" name="${key}" value="${value}" />`
            ).join('')}
        </form>
        <script>document.getElementById('payfastForm').submit();</script>
    `
    return formHtml
}

// Send payment to PayFast (API method)
export async function initiatePayment(communityId, userId, amount, itemName) {
    try {
        // First, create a payment record in our database
        const { data: payment, error } = await supabase
            .from('subscription_payments')
            .insert({
                community_id: communityId,
                user_id: userId,
                amount: amount,
                platform_fee: amount / 2,
                creator_earnings: amount / 2,
                currency: 'ZAR',
                status: 'pending'
            })
            .select()
            .single()

        if (error) throw error

        // Generate PayFast data
        const payfastData = {
            merchant_id: PAYFAST_MERCHANT_ID,
            merchant_key: PAYFAST_MERCHANT_KEY,
            return_url: process.env.REACT_APP_PAYFAST_RETURN_URL,
            cancel_url: process.env.REACT_APP_PAYFAST_CANCEL_URL,
            notify_url: process.env.REACT_APP_PAYFAST_NOTIFY_URL,
            m_payment_id: payment.id,
            amount: amount.toFixed(2),
            item_name: itemName,
            item_description: `Monthly subscription to ${itemName}`,
            custom_str1: communityId,
            custom_str2: userId,
            email_confirmation: '1',
            confirmation_address: 'info@predictfc.com'
        }

        return {
            success: true,
            paymentId: payment.id,
            payfastData: payfastData,
            payfastUrl: PAYFAST_URL
        }

    } catch (error) {
        console.error('Payment initiation error:', error)
        return {
            success: false,
            error: error.message
        }
    }
}

// Verify PayFast payment (ITN - Instant Transaction Notification)
export async function verifyPayment(paymentData) {
    try {
        // Generate signature
        const signature = generateSignature(paymentData)
        
        // Verify signature
        if (signature !== paymentData.signature) {
            return { success: false, error: 'Invalid signature' }
        }

        // Check if payment already processed
        const { data: existing } = await supabase
            .from('subscription_payments')
            .select('status')
            .eq('id', paymentData.m_payment_id)
            .single()

        if (existing && existing.status === 'success') {
            return { success: true, alreadyProcessed: true }
        }

        // Update payment status
        const { error } = await supabase
            .from('subscription_payments')
            .update({
                status: paymentData.payment_status === 'COMPLETE' ? 'success' : 'failed',
                transaction_id: paymentData.pf_payment_id,
                payment_method: paymentData.payment_method || 'payfast'
            })
            .eq('id', paymentData.m_payment_id)

        if (error) throw error

        // If payment successful, add user to community
        if (paymentData.payment_status === 'COMPLETE') {
            await addUserToCommunity(
                paymentData.m_payment_id,
                paymentData.custom_str1,
                paymentData.custom_str2
            )
        }

        return {
            success: true,
            paymentStatus: paymentData.payment_status
        }

    } catch (error) {
        console.error('Payment verification error:', error)
        return {
            success: false,
            error: error.message
        }
    }
}

// Add user to community after successful payment
async function addUserToCommunity(paymentId, communityId, userId) {
    try {
        // Check if already a member
        const { data: existing } = await supabase
            .from('community_members')
            .select('id')
            .eq('community_id', communityId)
            .eq('user_id', userId)
            .maybeSingle()

        if (existing) {
            return { success: true, alreadyMember: true }
        }

        // Add user as member
        await supabase
            .from('community_members')
            .insert({
                community_id: communityId,
                user_id: userId,
                role: 'member',
                status: 'active',
                expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
            })

        // Update member count
        const { data: communityData } = await supabase
            .from('communities')
            .select('member_count')
            .eq('id', communityId)
            .single()

        await supabase
            .from('communities')
            .update({
                member_count: (communityData?.member_count || 0) + 1
            })
            .eq('id', communityId)

        // Update the creator's earnings (they get 50%)
        const { data: creatorData } = await supabase
            .from('communities')
            .select('creator_id')
            .eq('id', communityId)
            .single()

        if (creatorData) {
            await supabase
                .from('profiles')
                .update({
                    total_earnings: supabase.rpc('increment_earnings', { 
                        user_id: creatorData.creator_id, 
                        amount: 25.00 
                    })
                })
                .eq('id', creatorData.creator_id)
        }

        return { success: true }

    } catch (error) {
        console.error('Error adding user to community:', error)
        return {
            success: false,
            error: error.message
        }
    }
}

// Generate signature for verification
function generateSignature(data) {
    // Remove signature from data
    const { signature, ...dataWithoutSignature } = data
    
    // Sort and serialize
    const serialized = Object.keys(dataWithoutSignature)
        .sort()
        .map(key => `${key}=${encodeURIComponent(dataWithoutSignature[key])}`)
        .join('&')
    
    // Simple MD5 hash (in production use proper crypto)
    // For Node.js environment
    if (typeof window === 'undefined') {
        const crypto = require('crypto')
        if (PAYFAST_PASSPHRASE) {
            return crypto.createHash('md5')
                .update(`${serialized}&passphrase=${encodeURIComponent(PAYFAST_PASSPHRASE)}`)
                .digest('hex')
        } else {
            return crypto.createHash('md5')
                .update(serialized)
                .digest('hex')
        }
    }
    
    // For browser environment - simplified (use a library in production)
    return serialized
}

// Get payment status
export async function getPaymentStatus(paymentId) {
    try {
        const { data, error } = await supabase
            .from('subscription_payments')
            .select('*')
            .eq('id', paymentId)
            .single()

        if (error) throw error
        return {
            success: true,
            payment: data
        }
    } catch (error) {
        console.error('Error getting payment status:', error)
        return {
            success: false,
            error: error.message
        }
    }
}
